#!/bin/bash
# WfDrL runner A (2 workers): graftE checks, then PV2 on 100k samples of the big sets
G=/home/koteitan/proofs/trio/tmp/wf/WfDrE/graftE.pkl
nice -n 15 python3 /home/koteitan/proofs/trio/tmp/wf/WfDrE/pv2.py 2 $G > /home/koteitan/proofs/trio/tmp/wf/WfDrL/pv2_graftE.jsonl 2>> /home/koteitan/proofs/trio/tmp/wf/WfDrL/runA.err
nice -n 15 python3 /home/koteitan/proofs/trio/tmp/wf/WfDrE/uaw2.py 2 $G > /home/koteitan/proofs/trio/tmp/wf/WfDrL/uaw2_graftE.jsonl 2>> /home/koteitan/proofs/trio/tmp/wf/WfDrL/runA.err
nice -n 15 python3 /home/koteitan/proofs/trio/tmp/wf/WfDrE/seedc.py 2 $G > /home/koteitan/proofs/trio/tmp/wf/WfDrL/seedc_graftE.jsonl 2>> /home/koteitan/proofs/trio/tmp/wf/WfDrL/runA.err
nice -n 15 python3 /home/koteitan/proofs/trio/tmp/wf/WfDrL/probe_dp0.py 2 $G > /home/koteitan/proofs/trio/tmp/wf/WfDrL/dp0_graftE.jsonl 2>> /home/koteitan/proofs/trio/tmp/wf/WfDrL/runA.err
LIMIT=100000 nice -n 15 python3 /home/koteitan/proofs/trio/tmp/wf/WfDrE/pv2.py 2 /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/deep3.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/deep2.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/t0ext.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/ext1x.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/graftBn.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/graftB.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/e3exp.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/Cprime.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/ext3s.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/ext1.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/expP.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/t2ext.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/ext2.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/ext2n2.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/expPt2.pkl /home/koteitan/proofs/trio/tmp/ytosk-handoff/sets/std_b.pkl  > /home/koteitan/proofs/trio/tmp/wf/WfDrL/pv2_big.jsonl 2>> /home/koteitan/proofs/trio/tmp/wf/WfDrL/runA.err
echo DONE >> /home/koteitan/proofs/trio/tmp/wf/WfDrL/runA.err
